&fit=crop&w=800&q=80', 249),\n(2, 2, 'Margherita Pizza', 'Classic delight with 100% real mozzarella cheese', 'https://images.unsplash.com/photo-1574071318508-1cdbab80d002?auto=format&fit=crop&w=800&q=80', 199),\n(3, 3, 'Chicken Tikka Burger', 'Spicy chicken tikka in a soft bun', 'https://images.unsplash.com/photo-1615719413546-198b25453f85?auto=format&fit=crop&w=800&q=80', 149),\n(4, 4, 'Hakka Noodles', 'Wok-tossed noodles with crunchy vegetables', 'https://images.unsplash.com/photo-1585032226651-759b368d7246?auto=format&fit=crop&w=800&q=80', 129),\n(5, 5, 'Masala Dosa', 'Crispy crepe stuffed with spiced potatoes', 'https://images.unsplash.com/photo-1589301760014-d929f39ce9b1?auto=format&fit=crop&w=800&q=80', 99),\n(6, 6, 'Chocolate Brownie', 'Warm gooey brownie with chocolate syrup', 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=800&q=80', 119),\n(7, 7, 'Cold Coffee', 'Chilled coffee blended with vanilla ice cream', 'https://images.unsplash.com/photo-1461023058943-07fcbe16d735?auto=format&fit=crop&w=800&q=80', 89),\n(8, 8, 'Quinoa Salad', 'Healthy bowl of quinoa, fresh veggies & vinaigrette', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80', 179),\n(9, 9, 'Pani Puri', 'Crispy puris filled with spicy tangy water', 'https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=800&q=80', 49),\n(10, 10, 'Hyderabadi Biryani', 'Aromatic basmati rice cooked with spices and meat', 'https://images.unsplash.com/photo-1589302168068-964664d93cb0?auto=format&fit=crop&w=800&q=80', 299);\n\n-- ITEM VARIANTS\nINSERT INTO item_variants (menu_item_id, name, price) VALUES\n(1, 'Large', 299),\n(2, 'Large', 249),\n(3, 'Large', 199),\n(4, 'Large', 179),\n(5, 'Large', 149),\n(6, 'Large', 169),\n(7, 'Large', 139),\n(8, 'Large', 229),\n(9, 'Large', 99),\n(10, 'Large', 349);\n\n-- ITEM ADDONS\nINSERT INTO item_addons (menu_item_id, name, price) VALUES\n(1, 'Extra Cheese', 30),\n(2, 'E